T = TypeVar("T")

structlogger = structlog.get_logger()

# ``agent_message_type`` value tagging a filler agent utterance.
FILLER_MESSAGE_TYPE = "filler_message"
# Metadata key recording where a v2 agent response came from — a verbatim
# response template, free LLM text, or a filler. Read by the Inspector to
# label responses; namespaced to avoid colliding with the v1
# ``agent_message_type`` vocabulary.
RESPONSE_SOURCE_METADATA_KEY = "mantle_response_source"
# v1-compatible key carrying the response template name (``utter_*``).
UTTER_ACTION_METADATA_KEY = "utter_action"


class ResponseSource(str, Enum):
    """Origin of an agent response emitted during an engine turn."""

    VERBATIM = "verbatim"
    REPHRASED = "rephrased"
    LLM = "llm"
    FILLER = "filler"


def _wire_buttons(buttons: tuple[ResponseButton, ...]) -> list[dict[str, str]]:
    """Serialize delivery-ready buttons to the CALM ``BotUttered`` / channel shape.

    Prefer buttons already passed through
    :func:`~rasa.mantle.orchestration.memory_utils.resolve_response_buttons`.
    A missing ``payload`` is filled from ``title`` so delivery still succeeds if a
    call site skips resolution.
    """
    wire: list[dict[str, str]] = []
    for button in buttons:
        payload = button.payload
        if payload is None:
            structlogger.warning(
                "turn_context.button_payload_defaulted_from_title",
            )
            payload = button.title
        wire.append({"title": button.title, "payload": payload})
    return wire


def _bot_uttered_metadata(
    *,
    variant_metadata: Mapping[str, Any] | None,
    is_filler: bool,
    response_name: Optional[str],
    response_source: Optional[ResponseSource],
    llm_total_time_ms: Optional[float] = None,
    llm_time_to_first_token_ms: Optional[float] = None,
) -> dict[str, object]:
    """Merge variant authoring metadata with engine delivery metadata.

    Variant keys are preserved; engine keys (``utter_action``,
    ``mantle_response_source``, timing, filler type) win on collision.
    """
    metadata: dict[str, object] = dict(variant_metadata or {})
    metadata[RESPONSE_SOURCE_METADATA_KEY] = (
        MessageTurnContext._resolve_response_source(
            is_filler, response_name, response_source
        ).value
    )
    if is_filler:
        metadata[BOT_UTTERANCE_AGENT_MESSAGE_TYPE_KEY] = FILLER_MESSAGE_TYPE
    if response_name is not None:
        metadata[UTTER_ACTION_METADATA_KEY] = response_name
    if llm_time_to_first_token_ms is not None:
        metadata[LLM_TIME_TO_FIRST_TOKEN_MS_KEY] = llm_time_to_first_token_ms
    if llm_total_time_ms is not None:
        metadata[LLM_TOTAL_TIME_MS_KEY] = llm_total_time_ms
    return metadata


_current_turn_ctx: ContextVar["MessageTurnContext"] = ContextVar("message_turn_ctx")


class _HookBufferedOutputChannel:
    """Discard provider chunks until the completed utterance passes hooks."""

    supports_response_writer = False

    async def send_response_chunk_start(self, recipient_id: str, **kwargs: Any) -> None:
        return None

    async def send_response_chunk(
        self, recipient_id: str, chunk: str, **kwargs: Any
    ) -> None:
        return None

    async def send_response_chunk_end(self, recipient_id: str, **kwargs: Any) -> None:
        return None


class MessageTurnContext:
    """Ambient context for the message the agent is currently handling.

    One instance per engine turn. Use it as an async context manager so the
    context var is set on entry and reset on exit::

        async with MessageTurnContext(handle, turn, channel, sender_id, token):
            await orchestrator.run_turn(handle, turn)

    Inside that block any code can reach the live context via
    :func:`current_turn_context` and emit a response with
    :meth:`send` — no parameter threading required.
    """

    def __init__(
        self,
        tracker_handle: TrackerHandle,
        turn: IncomingTurn,
        output_channel: "OutputChannel",
        sender_id: str,
        cancellation: Optional["CancellationToken"] = None,
        consume_pending_input: Optional[
            Callable[[TrackerHandle], Awaitable[Optional[IncomingTurn]]]
        ] = None,
        hooks: Optional[HookRegistry] = None,
        resolve_rejection_fallback: Optional[
            Callable[[Optional[str]], OutgoingRejectionFallback]
        ] = None,
    ) -> None:
        self._tracker_handle = tracker_handle
        self._turn = turn
        self._output_channel = output_channel
        self._sender_id = sender_id
        self._cancellation = cancellation
        self._consume_pending_input = consume_pending_input
        self._hooks = hooks if hooks is not None else HookRegistry.empty()
        self._resolve_rejection_fallback = resolve_rejection_fallback
        self._hook_buffered_output_channel = _HookBufferedOutputChannel()
        self._reset_token: Optional[Token] = None
        self._agent_messages: List[str] = []
        self._turn_start_time: Optional[float] = None
        self._skipped_collects: List[SkippedCollectView] = []
        self._activated_frame_groups: List[FrozenSet[str]] = []
        self._streamed_event_id: Optional[str] = None
        self._tool_stream_open = False
        self._tool_stream_parts: List[str] = []
        self._tool_stream_writer: Optional[Any] = None
        self._tool_stream_chunk_session = False
        self._tool_stream_event_id: Optional[str] = None

    @property
    def tracker_handle(self) -> TrackerHandle:
        """Live tracker wrapper for the current turn."""
        return self._tracker_handle

    @property
    def turn(self) -> IncomingTurn:
        """The incoming user turn being handled."""
        return self._turn

    @property
    def output_channel(self) -> "OutputChannel":
        """Output channel for the current turn (text or streaming delivery)."""
        return self._output_channel

    @property
    def llm_streaming_output_channel(self) -> "OutputChannel":
        """Channel used while assembling an LLM streaming response.

        Outgoing modifiers operate on a completed utterance, so provider chunks
        are suppressed whenever a ``modify_outgoing_text`` hook is registered.
        Observe-only hooks do not buffer tokens. The accepted or fallback text
        is emitted once from :meth:`record_streamed_message` after a modifier.
        """
        if has_outgoing_text_modifier(self._hooks):
            return self._hook_buffered_output_channel  # type: ignore[return-value]
        return self._output_channel

    @property
    def sender_id(self) -> str:
        """Conversation id passed to the output channel."""
        return self._sender_id

    @property
    def agent_messages(self) -> List[str]:
        """Non-filler agent messages sent so far this turn, in order.

        Filler / "thinking" utterances are excluded so this reads as the
        substantive turn output (used e.g. as the ``run_turn`` span output).
        """
        return list(self._agent_messages)

    @property
    def turn_start_time(self) -> Optional[float]:
        """Per-turn start time, or ``None`` before the context is entered."""
        return self._turn_start_time

    @property
    def is_cancelled(self) -> bool:
        """Whether execution has been cancelled, such as on call teardown.

        The token is created per turn by the caller, so a set token always
        reflects an interrupt of *this* turn.
        """
        return self._cancellation is not None and self._cancellation.is_cancelled

    @property
    def is_interrupted(self) -> bool:
        """Whether output is suppressed while execution continues."""
        return self._output_channel.is_response_interrupted

    @property
    def skipped_collects(self) -> tuple[SkippedCollectView, ...]:
        """Collects skipped this user turn because the value was already set."""
        return tuple(self._skipped_collects)

    def record_skipped_collect(self, field_name: str, display_value: str) -> None:
        """Remember a skipped collect for this turn's mixed-control prompt.

        Duplicate field names keep the first recorded display value.
        """
        for existing in self._skipped_collects:
            if existing.field_name == field_name:
                return
        self._skipped_collects.append(
            SkippedCollectView(field_name=field_name, display_value=display_value)
        )

    def record_activated_frames(self, frame_ids: FrozenSet[str]) -> None:
        """Remember the stack frames of the skill one ``activate`` call made active."""
        self._activated_frame_groups.append(frame_ids)

    def take_activated_frame_groups(self) -> List[FrozenSet[str]]:
        """Return and clear the frame groups recorded since the last take."""
        groups = self._activated_frame_groups
        self._activated_frame_groups = []
        return groups

    async def take_pending_input(self) -> bool:
        """Take in user input that arrived while this turn was running.

        Appends the input to the live tracker and makes the latest user input the
        current :attr:`turn`. Output produced for the previous input is stopped,
        and the floor is handed back so replies to the new input are heard.

        Returns:
            Whether new user input was taken in; the caller then restarts the turn
            with it.
        """
        if (
            self._consume_pending_input is None
            or self._turn.trigger is IncomingTurnTrigger.SESSION_START
        ):
            return False
        turn = await self._consume_pending_input(self._tracker_handle)
        if turn is None:
            return False
        self._turn = turn
        self._skipped_collects.clear()
        self._activated_frame_groups.clear()
        if not self.is_interrupted:
            await self._output_channel.interrupt_response()
        await self._output_channel.resume_response()
        return True

    def begin_streamed_response(self) -> Optional[str]:
        """Reserve the event id of a streamed voice response before its first token.

        The channel stamps playback markers with this id while streaming, before
        the ``BotUttered`` exists; :meth:`record_streamed_message` then assigns it
        to that event so a barge-in can name the response it cut off.
        """
        self._streamed_event_id = new_event_id() if self._turn.is_voice else None
        return self._streamed_event_id

    async def run_cancellable(self, awaitable: Awaitable[T]) -> T:
        """Await *awaitable*, aborting immediately when this turn is cancelled.

        Races the work against the per-turn cancellation token so an in-flight
        LLM call, tool call, or skill step does not block call teardown. Raises
        :exc:`~rasa.agents.core.cancellation.OperationCancelled` when cancel
        wins. Without a token, behaves as a plain ``await``.
        """
        if self._cancellation is None:
            return await awaitable
        return await self._cancellation.race(awaitable)

    async def send(
        self,
        text: str,
        *,
        is_filler: bool = False,
        response_name: Optional[str] = None,
        response_source: Optional[ResponseSource] = None,
        llm_total_time_ms: Optional[float] = None,
        buttons: tuple[ResponseButton, ...] = (),
        variant_metadata: Mapping[str, Any] | None = None,
        discarded: bool = False,
    ) -> None:
        """Emit one agent response: record it on the tracker and deliver it.

        This is the single seam for response delivery in a turn. It appends a
        ``BotUttered`` event (so the message appears in conversation history)
        and forwards the text to the output channel — via ``send_response`` when
        *buttons* are present, otherwise ``send_text_message``.

        Muted responses are recorded without delivery. Cancelled turns drop
        the message entirely. A send while a tool stream is open is rejected
        so the two deliveries cannot share one voice session. Outgoing hooks
        run only after those checks; if cancellation lands while a hook is in
        flight, the hook still finishes and the send is then dropped.

        Args:
            text: The message to send to the user.
            is_filler: ``True`` when *text* is a filler / "thinking" message
                emitted before tool calls. The event is tagged with the filler
                ``agent_message_type`` metadata, and the channel is notified
                after the send so voice can pace the gap before the next
                utterance.
            response_name: Name of the response template the text came from
                (``utter_*``), stamped onto the event metadata for
                observability. ``None`` for free-form LLM text.
            response_source: Explicit provenance label for
                ``mantle_response_source``. When omitted, inferred from
                *is_filler* and *response_name*.
            llm_total_time_ms: Total LLM generation time in milliseconds.
            buttons: Static buttons from the selected response variant. When
                non-empty, ``BotUttered.data["buttons"]`` is set and the channel
                receives ``send_response`` instead of ``send_text_message``.
            variant_metadata: Authoring metadata from the selected response
                variant, merged into ``BotUttered.metadata``.
            discarded: When ``True``, stamp the stored ``BotUttered`` so LLM
                history omits it. Used for incoming-message rejection replies.

        Raises:
            RuntimeError: When a tool stream is still open.
        """
        if self._tool_stream_open:
            raise RuntimeError("Cannot send while a tool stream is open.")
        if self.is_cancelled:
            structlogger.debug("turn_context.send_skipped_cancelled")
            voice_tracing.get_current_handle_turn_recorder().record_response_dropped(
                text=text, is_filler=is_filler
            )
            return
        decision = await apply_outgoing_text_hooks(
            self._hooks,
            text,
            sender_id=self._sender_id,
            channel=ChannelInfo(name=output_channel_name(self._output_channel)),
            is_voice=self._turn.is_voice,
        )
        if self.is_cancelled:
            structlogger.debug("turn_context.send_skipped_cancelled_after_hook")
            voice_tracing.get_current_handle_turn_recorder().record_response_dropped(
                text=text, is_filler=is_filler
            )
            return
        await self._commit_outgoing_text(
            decision=decision,
            is_filler=is_filler,
            response_name=response_name,
            response_source=response_source,
            llm_total_time_ms=llm_total_time_ms,
            buttons=buttons,
            variant_metadata=variant_metadata,
            streamed=False,
            emit_streamed_text=False,
            discarded=discarded,
        )

    async def record_streamed_message(
        self,
        text: str,
        *,
        llm_time_to_first_token_ms: Optional[float] = None,
        llm_total_time_ms: Optional[float] = None,
        is_filler: bool = False,
        response_name: Optional[str] = None,
        response_source: Optional[ResponseSource] = None,
        buttons: tuple[ResponseButton, ...] = (),
        variant_metadata: Mapping[str, Any] | None = None,
    ) -> None:
        """Record completed LLM text and finish its streaming delivery.

        Without an outgoing modifier, ``acompletion_with_streaming`` has already
        sent *text* via ``send_response_chunk``. When a modifier is configured,
        provider chunks were buffered instead; this method hooks the assembled
        text and emits the accepted or fallback utterance. Observe-only hooks
        still run here and do not replay tokens. Non-streaming turns keep using
        :meth:`send`. Buttons are delivered via
        :meth:`OutputChannel.send_buttons` without repeating the text. Muted
        responses remain in history, with buttons and buffered text withheld.

        Args:
            text: The streamed message to record.
            llm_time_to_first_token_ms: Time to the first content token, in ms.
            llm_total_time_ms: Total LLM generation time in milliseconds.
            is_filler: ``True`` when *text* is a filler / "thinking" message.
            response_name: Name of the response template the text came from
                (``utter_*``). ``None`` for free-form LLM text.
            response_source: Explicit provenance label for
                ``mantle_response_source``. When omitted, inferred from
                *is_filler* and *response_name*.
            buttons: Static buttons from the selected response variant. Stamped
                on ``BotUttered.data`` so tracker-based clients (Inspector) match
                the authored options, and delivered via
                :meth:`OutputChannel.send_buttons` so live-streaming channels
                get a second, text-less emit after the streamed utterance.
            variant_metadata: Authoring metadata from the selected response
                variant, merged into ``BotUttered.metadata``.
        """
        if self.is_cancelled:
            structlogger.debug("turn_context.record_streamed_message_skipped_cancelled")
            voice_tracing.get_current_handle_turn_recorder().record_response_dropped(
                text=text, is_filler=is_filler
            )
            return
        buffered = has_outgoing_text_modifier(self._hooks)
        decision = await apply_outgoing_text_hooks(
            self._hooks,
            text,
            sender_id=self._sender_id,
            channel=ChannelInfo(name=output_channel_name(self._output_channel)),
            is_voice=self._turn.is_voice,
        )
        if self.is_cancelled:
            structlogger.debug(
                "turn_context.record_streamed_message_skipped_cancelled_after_hook"
            )
            voice_tracing.get_current_handle_turn_recorder().record_response_dropped(
                text=text, is_filler=is_filler
            )
            return
        await self._commit_outgoing_text(
            decision=decision,
            is_filler=is_filler,
            response_name=response_name,
            response_source=response_source,
            llm_total_time_ms=llm_total_time_ms,
            llm_time_to_first_token_ms=llm_time_to_first_token_ms,
            buttons=buttons,
            variant_metadata=variant_metadata,
            streamed=True,
            emit_streamed_text=buffered,
        )

    def _outgoing_rejection_fallback(
        self, response_message: Optional[str]
    ) -> Optional[OutgoingRejectionFallback]:
        """Resolve named fallback via the processor-owned SkillExecutor.

        Production always binds a resolver. When the binder is missing, log and
        drop the send so the blocked draft is never uttered.
        """
        if self._resolve_rejection_fallback is None:
            structlogger.warning(
                "mantle.turn_context.outgoing_rejection_fallback_unbound",
                response_message=response_message,
            )
            return None
        return self._resolve_rejection_fallback(response_message)

    async def _commit_outgoing_text(
        self,
        *,
        decision: "OutgoingTextDecision",
        is_filler: bool,
        response_name: Optional[str],
        response_source: Optional[ResponseSource],
        llm_total_time_ms: Optional[float],
        buttons: tuple[ResponseButton, ...],
        variant_metadata: Mapping[str, Any] | None,
        streamed: bool,
        emit_streamed_text: bool,
        llm_time_to_first_token_ms: Optional[float] = None,
        discarded: bool = False,
    ) -> None:
        """Store and deliver post-hook text on the send or streaming path.

        A rejected draft was never uttered, so nothing but the text the user
        actually receives reaches the tracker. The fallback is the template the
        bot builder wrote for this rejection, so it is delivered as authored
        and is not passed through the outgoing-text hooks again.
        """
        if decision.rejected:
            # The modifier blocked the draft. ``response_message`` is a
            # responses.yml name; resolve it to the text, buttons, and metadata
            # the user should see instead.
            fallback = self._outgoing_rejection_fallback(decision.response_message)
            if fallback is None:
                return
            # The user receives a template reply, not the blocked draft, so drop
            # the draft's filler flag, provenance, and LLM timings.
            text = fallback.text
            is_filler = False
            response_name = fallback.response_name
            response_source = None
            llm_total_time_ms = None
            llm_time_to_first_token_ms = None
            buttons = fallback.buttons
            variant_metadata = fallback.variant_metadata
        else:
            text = decision.text
        metadata = _bot_uttered_metadata(
            variant_metadata=variant_metadata,
            is_filler=is_filler,
            response_name=response_name,
            response_source=response_source,
            llm_total_time_ms=llm_total_time_ms,
            llm_time_to_first_token_ms=llm_time_to_first_token_ms,
        )
        # Incoming-message rejection replies are stored but omitted from LLM
        # history, so the blocked user text and this reply stay out of the prompt.
        if discarded:
            metadata[DISCARDED_EVENT_METADATA_KEY] = True
        wire_buttons = _wire_buttons(buttons)
        data: dict[str, object] = {"buttons": wire_buttons} if wire_buttons else {}
        if self.is_interrupted:
            metadata[RESPONSE_UNHEARD_METADATA_KEY] = True
        event = BotUttered(text=text, data=data, metadata=metadata)
        if streamed:
            event.event_id = self._streamed_event_id
            self._streamed_event_id = None
        self._tracker_handle.apply_events([event])
        turn_tracing.record_turn_bot_message()
        delivery_kwargs: dict[str, str] = {}
        if self._turn.is_voice and event.event_id is not None:
            delivery_kwargs[RESPONSE_EVENT_ID_METADATA_KEY] = event.event_id
        if not self.is_interrupted:
            if streamed:
                # Tokens already went to the channel unless a modifier forced
                # them to be held. Buttons are a separate, text-less message.
                if emit_streamed_text:
                    await self._emit_streamed_text(text, **delivery_kwargs)
                if wire_buttons:
                    await self._output_channel.send_buttons(
                        self._sender_id, wire_buttons
                    )
            elif wire_buttons:
                await self._output_channel.send_response(
                    self._sender_id,
                    {"text": text, "buttons": wire_buttons, **delivery_kwargs},
                )
            else:
                await self._output_channel.send_text_message(
                    self._sender_id, text, **delivery_kwargs
                )
            self._output_channel.note_last_streamed_bot_message_was_filler(is_filler)
        if is_filler and not self.is_interrupted:
            voice_tracing.get_current_handle_turn_recorder().record_filler_sent(
                response_name=response_name, text=text
            )
        elif not is_filler:
            self._agent_messages.append(text)
        # Inspector redraws from after_action_executed; the turn-end hook fires
        # only once, so each committed response publishes its own update.
        await self._publish_incremental_response()

    def begin_tool_stream(self) -> None:
        """Open the single tool-owned stream for this turn.

        Playback stays closed until the first non-empty chunk. A second open
        while this stream is still active is rejected so two streams cannot
        share one voice session. On voice, the event id of the message the
        stream records is reserved now, so playback markers can name it while
        it plays, before the message exists.

        Raises:
            RuntimeError: When a tool stream is already open.
        """
        if self._tool_stream_open:
            raise RuntimeError("Only one tool stream can be open.")
        self._tool_stream_open = True
        self._tool_stream_parts = []
        self._tool_stream_writer = None
        self._tool_stream_chunk_session = False
        self._tool_stream_event_id = new_event_id() if self._turn.is_voice else None

    async def write_tool_stream(self, chunk: str) -> None:
        """Deliver one text piece of the open tool stream.

        An empty string is ignored and does not open playback. A piece is
        also ignored once the turn is cancelled, so nothing further is sent.
        On a channel that streams, the first accepted piece opens the session
        and each piece is delivered immediately. The piece is kept for the
        recorded message only after that delivery returns. On a channel that
        does not stream, or when a ``modify_outgoing_text`` hook is registered,
        pieces are held until :meth:`close_tool_stream` so hooks can rewrite or
        reject the assembled utterance.

        Raises:
            RuntimeError: When no tool stream is open.
        """
        if not self._tool_stream_open:
            raise RuntimeError("No tool stream is open.")
        if not chunk or self.is_cancelled:
            return
        await self._deliver_tool_stream_chunk(chunk)
        self._tool_stream_parts.append(chunk)

    async def close_tool_stream(
        self,
        *,
        interrupted: bool = False,
        buttons: tuple[ResponseButton, ...] = (),
        variant_metadata: Mapping[str, Any] | None = None,
    ) -> None:
        """Finish the open tool stream and record what the user received.

        No accepted text records nothing. A streaming session that was opened
        and then accepted nothing is closed without a record. A finished
        streaming session is closed, then one ``BotUttered`` is recorded
        without sending the text again. A buffered session — non-streaming
        channel, or a ``modify_outgoing_text`` hook — delivers the full text
        through :meth:`send`, which applies outgoing hooks before storage.

        An interrupted stream sends nothing further. Text already handed to a
        streaming channel is recorded. Text that was only buffered, because
        the channel does not stream or a modifier forced buffering, is
        discarded. A second close is a no-op.

        Args:
            interrupted: ``True`` when the tool raised or the turn was cancelled
                before the stream finished.
            buttons: Buttons for a finished stream. Ignored when *interrupted*.
            variant_metadata: Authoring metadata for a finished stream. Ignored
                when *interrupted*.
        """
        if not self._tool_stream_open:
            return
        text = "".join(self._tool_stream_parts)
        writer = self._tool_stream_writer
        chunk_session = self._tool_stream_chunk_session
        response_event_id = self._tool_stream_event_id
        self._clear_tool_stream()
        if not text:
            await self._abandon_undelivered_tool_stream(writer, chunk_session)
            return
        if writer is not None:
            await self._finish_writer_tool_stream(
                writer,
                text,
                interrupted,
                buttons=buttons,
                variant_metadata=variant_metadata,
                response_event_id=response_event_id,
            )
            return
        if chunk_session:
            await self._finish_chunk_tool_stream(
                text,
                interrupted,
                buttons=buttons,
                variant_metadata=variant_metadata,
                response_event_id=response_event_id,
            )
            return
        if interrupted:
            return
        await self.send(text, buttons=buttons, variant_metadata=variant_metadata)

    async def record_delivered_tool_stream(
        self,
        text: str,
        *,
        interrupted: bool,
        buttons: tuple[ResponseButton, ...] = (),
        variant_metadata: Mapping[str, Any] | None = None,
        response_event_id: Optional[str] = None,
    ) -> None:
        """Record text a tool stream already handed to the channel.

        Unlike :meth:`record_streamed_message`, this still records when the
        turn is cancelled. Text the channel already accepted stays on the
        tracker. On a voice response writer, accepted means queued for
        playback, which can be before the user hears it. An interrupted stream
        records that text only: no buttons and no second delivery of the text.
        A cancellation observed here, including one that lands while the
        channel is closing, is treated as an interrupt, so buttons and
        authoring metadata for a finished stream are dropped.

        Outgoing observers run once on the completed string. A rewrite or
        rejection is ignored, because the channel already accepted *text*.
        A cancellation that lands during that hook still stores *text*, and
        drops buttons and authoring metadata.

        Text withheld after a barge-in is recorded as not heard, with its
        buttons stored but not sent, as muted responses are on :meth:`send`.

        Args:
            text: Concatenation of pieces the channel already accepted.
            interrupted: ``True`` when the stream stopped before it finished.
            buttons: Buttons for a finished stream. Ignored when *interrupted*.
            variant_metadata: Authoring metadata merged into the event. Ignored
                when the stream is interrupted or the turn is already cancelled.
            response_event_id: Event id reserved when the stream opened, which its
                playback markers carry. ``None`` keeps a generated id.
        """
        if self.is_cancelled:
            interrupted = True
        # The channel already accepted this text. Observers still see it.
        # A rewrite or rejection cannot replace what was queued. A cancel
        # during the await must not skip the record, and it drops buttons.
        hook_cancelled: BaseException | None = None
        try:
            await apply_outgoing_text_hooks(
                self._hooks,
                text,
                sender_id=self._sender_id,
                channel=ChannelInfo(name=output_channel_name(self._output_channel)),
                is_voice=self._turn.is_voice,
            )
        except asyncio.CancelledError as exc:
            hook_cancelled = exc
        if self.is_cancelled or hook_cancelled is not None:
            interrupted = True
        delivered_buttons = () if interrupted else buttons
        if interrupted:
            variant_metadata = None
        metadata = _bot_uttered_metadata(
            variant_metadata=variant_metadata,
            is_filler=False,
            response_name=None,
            response_source=None,
        )
        muted = self.is_interrupted
        if muted:
            metadata[RESPONSE_UNHEARD_METADATA_KEY] = True
        wire_buttons = _wire_buttons(delivered_buttons)
        data: dict[str, object] = {"buttons": wire_buttons} if wire_buttons else {}
        event = BotUttered(text=text, data=data, metadata=metadata)
        if response_event_id is not None:
            event.event_id = response_event_id
        self._tracker_handle.apply_events([event])
        turn_tracing.record_turn_bot_message()
        if not muted:
            if wire_buttons:
                await self._output_channel.send_buttons(self._sender_id, wire_buttons)
            self._output_channel.note_last_streamed_bot_message_was_filler(False)
        self._agent_messages.append(text)
        await self._publish_incremental_response()
        if hook_cancelled is not None:
            raise hook_cancelled

    async def _finish_writer_tool_stream(
        self,
        writer: Any,
        text: str,
        interrupted: bool,
        *,
        buttons: tuple[ResponseButton, ...],
        variant_metadata: Mapping[str, Any] | None,
        response_event_id: Optional[str],
    ) -> None:
        """Close a response-writer session and record the delivered text."""
        if interrupted:
            writer.interrupt()
        else:
            writer.finish()
        await self._record_closed_tool_stream(
            text,
            interrupted,
            buttons=buttons,
            variant_metadata=variant_metadata,
            response_event_id=response_event_id,
        )

    async def _finish_chunk_tool_stream(
        self,
        text: str,
        interrupted: bool,
        *,
        buttons: tuple[ResponseButton, ...],
        variant_metadata: Mapping[str, Any] | None,
        response_event_id: Optional[str],
    ) -> None:
        """Close a chunk session and record the delivered text.

        Text the channel already accepted must stay on the tracker even when
        end-of-stream cleanup fails. On an interrupt, that cleanup error is
        suppressed so it does not replace the error that stopped the tool.
        On a finished stream, the cleanup error is re-raised after the record.
        """
        close_error: BaseException | None = None
        try:
            if interrupted:
                with contextlib.suppress(BaseException):
                    await self._output_channel.send_response_chunk_end(
                        self._sender_id, interrupted=True
                    )
            else:
                try:
                    await self._output_channel.send_response_chunk_end(self._sender_id)
                except BaseException as exc:
                    close_error = exc
        finally:
            await self._record_closed_tool_stream(
                text,
                interrupted,
                buttons=buttons,
                variant_metadata=variant_metadata,
                response_event_id=response_event_id,
            )
        if close_error is not None:
            raise close_error

    async def _record_closed_tool_stream(
        self,
        text: str,
        interrupted: bool,
        *,
        buttons: tuple[ResponseButton, ...],
        variant_metadata: Mapping[str, Any] | None,
        response_event_id: Optional[str],
    ) -> None:
        """Record a closed stream, dropping buttons and metadata when interrupted."""
        await self.record_delivered_tool_stream(
            text,
            interrupted=interrupted,
            buttons=() if interrupted else buttons,
            variant_metadata=None if interrupted else variant_metadata,
            response_event_id=response_event_id,
        )

    async def _abandon_undelivered_tool_stream(
        self, writer: Any, chunk_session: bool
    ) -> None:
        """Close a session that accepted no text, without recording a message."""
        if writer is not None:
            writer.interrupt()
            return
        if not chunk_session:
            return
        with contextlib.suppress(BaseException):
            await self._output_channel.send_response_chunk_end(
                self._sender_id, interrupted=True
            )

    def _clear_tool_stream(self) -> None:
        """Drop tool-stream session state so a later message can open one."""
        self._tool_stream_open = False
        self._tool_stream_parts = []
        self._tool_stream_writer = None
        self._tool_stream_chunk_session = False
        self._tool_stream_event_id = None

    def _tool_stream_start_kwargs(self) -> dict[str, str]:
        """Delivery kwargs that let playback markers name the stream's message."""
        if self._tool_stream_event_id is None:
            return {}
        return {RESPONSE_EVENT_ID_METADATA_KEY: self._tool_stream_event_id}

    async def _deliver_tool_stream_chunk(self, chunk: str) -> None:
        """Send *chunk* now, or keep it buffered until close.

        Outgoing modifiers operate on a completed utterance, so chunks are not
        sent while a ``modify_outgoing_text`` hook is registered. The same
        buffering applies when the channel cannot stream. Observe-only hooks do
        not suppress live delivery.
        """
        if has_outgoing_text_modifier(self._hooks):
            return
        if self._tool_stream_writer is not None:
            self._tool_stream_writer.write(chunk)
            return
        if self._tool_stream_chunk_session:
            await self._output_channel.send_response_chunk(
                recipient_id=self._sender_id,
                chunk=chunk,
            )
            return
        if self._output_channel.supports_response_writer and caller_requested_streaming(
            self._output_channel
        ):
            self._tool_stream_writer = self._output_channel.open_response(
                self._sender_id, **self._tool_stream_start_kwargs()
            )
            self._tool_stream_writer.write(chunk)
            return
        if caller_requested_streaming(self._output_channel):
            self._tool_stream_chunk_session = True
            await self._output_channel.send_response_chunk_start(
                self._sender_id, **self._tool_stream_start_kwargs()
            )
            await self._output_channel.send_response_chunk(
                recipient_id=self._sender_id,
                chunk=chunk,
            )

    async def _emit_streamed_text(self, text: str, **kwargs: Any) -> None:
        """Emit one whole post-hook utterance through the streaming protocol.

        Writer-capable channels (voice) enqueue through ``open_response`` so
        delivery uses the same serialized worker as live LLM streaming.
        """
        if self._output_channel.supports_response_writer:
            writer = self._output_channel.open_response(self._sender_id, **kwargs)
            writer.write(text)
            writer.finish()
            return
        await self._output_channel.send_response_chunk_start(self._sender_id, **kwargs)
        await self._output_channel.send_response_chunk(self._sender_id, text, **kwargs)
        await self._output_channel.send_response_chunk_end(self._sender_id, **kwargs)

    async def _publish_incremental_response(self) -> None:
        """Push the just-committed response to live tracker subscribers.

        A Mantle turn commits several ``BotUttered`` events but only fires
        ``after_prediction_loop_end`` once, at turn end. Subscribers that render
        the conversation from tracker dumps (the Inspector) would therefore show
        every response of the turn at once. Firing ``after_action_executed`` per
        response makes them re-render as soon as each response is produced.

        Awaitables returned by hook implementations (e.g. the voice channel's
        language update) are gathered with ``return_exceptions=True`` and their
        errors logged — mirroring the processor's ``after_action_executed`` path.
        A failing callback must not propagate out of response delivery, since the
        message has already been committed and streamed; letting it escape would
        abort the rest of the turn and skip finalization.
        """
        import asyncio
        import inspect

        from rasa.plugin import plugin_manager

        results = plugin_manager().hook.after_action_executed(
            tracker=self._tracker_handle.tracker
        )
        awaitables = [result for result in results if inspect.isawaitable(result)]
        if not awaitables:
            return
        hook_errors = await asyncio.gather(*awaitables, return_exceptions=True)
        for index, hook_error in enumerate(hook_errors):
            if isinstance(hook_error, Exception):
                structlogger.exception(
                    "mantle.turn_context.after_action_executed.exception",
                    hook_result_index=index,
                    error=hook_error,
                )

    @staticmethod
    def _resolve_response_source(
        is_filler: bool,
        response_name: Optional[str],
        response_source: Optional[ResponseSource],
    ) -> ResponseSource:
        """Classify a response as filler, verbatim, rephrased, or LLM text."""
        if response_source is not None:
            return response_source
        if is_filler:
            return ResponseSource.FILLER
        if response_name is not None:
            return ResponseSource.VERBATIM
        return ResponseSource.LLM

    async def __aenter__(self) -> "MessageTurnContext":
        """Bind this context as the ambient turn context."""
        self._turn_start_time = time.time()
        structlogger.debug(
            "mantle.turn_context.output_channel",
            channel=type(self._output_channel).__name__,
            supports_streaming=self._output_channel.supports_streaming,
        )
        self._reset_token = _current_turn_ctx.set(self)
        return self

    async def __aexit__(self, *exc_info: object) -> None:
        """Restore the previous ambient turn context."""
        if self._reset_token is not None:
            _current_turn_ctx.reset(self._reset_token)
            self._reset_token = None


def current_turn_context() -> MessageTurnContext:
    """Return the ambient :class:`MessageTurnContext` for the active turn.

    Raises:
        LookupError: when called outside an established turn context.
    """
    return _current_turn_ctx.get()


def skipped_collects_for_current_turn() -> tuple[SkippedCollectView, ...]:
    """Skip facts recorded this user turn, or empty outside a turn context."""
    try:
        return current_turn_context().skipped_collects
    except LookupError:
        return ()
